import { Component, computed, input } from '@angular/core';

/** 1 dòng trong bảng xếp hạng ngang. color = token/màu tuỳ chọn (mặc định màu chính). */
export interface HrmBarListItem {
  label: string;
  value: number;
  color?: string;
}

/** hrm-bar-list — xếp hạng ngang: mỗi dòng = nhãn + thanh tỉ lệ + số. So sánh nhanh
 *  top phòng ban theo headcount/OT/nghỉ phép trên dashboard. Thanh dài nhất = giá trị lớn nhất. */
@Component({
  selector: 'hrm-bar-list',
  template: `
    @for (r of rows(); track r.label) {
      <div class="bl-row">
        <div class="bl-bar-wrap">
          <div class="bl-bar" [style.width.%]="r.pct" [style.background]="r.bg"></div>
          <span class="bl-label">{{ r.label }}</span>
        </div>
        <span class="bl-value">{{ format()(r.value) }}</span>
      </div>
    }
  `,
  host: { class: 'hrm-bar-list' },
  styles: [`
:host { display: flex; flex-direction: column; gap: 8px; width: 100%; }
.bl-row { display: flex; align-items: center; gap: 12px; }
.bl-bar-wrap { position: relative; flex: 1; min-width: 0; height: 30px; border-radius: var(--radius-sm); overflow: hidden; }
.bl-bar { position: absolute; inset: 0 auto 0 0; border-radius: var(--radius-sm);
  transition: width var(--duration-normal, .25s) var(--ease-out, ease); }
.bl-label { position: relative; display: inline-flex; align-items: center; height: 100%;
  padding: 0 10px; font-size: var(--fs-13); color: var(--text-body);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.bl-value { flex: none; min-width: 40px; text-align: right; font-size: var(--fs-13);
  color: var(--text-strong); font-variant-numeric: tabular-nums; }
  `],
})
export class HrmBarList {
  readonly items = input<HrmBarListItem[]>([]);
  /** Định dạng số hiển thị (VD thêm đơn vị) — bên gọi cấp. */
  readonly format = input<(v: number) => string>((v) => String(v));

  protected readonly rows = computed(() => {
    const items = this.items();
    const max = Math.max(...items.map((i) => i.value), 1);
    return items.map((i) => ({
      label: i.label,
      value: i.value,
      pct: Math.max(0, Math.min(100, (i.value / max) * 100)),
      // Thanh = màu pha 18% trên nền — chữ đen đọc được trên mọi hue.
      bg: `color-mix(in srgb, ${i.color || 'var(--data-1)'} 18%, transparent)`,
    }));
  });
}
